---刷新信息面板
---@field type integer
---@field cardData table @卡牌信息
---@field curChooseId number
function UIFightChooseCardsFishNode:RefreshLeftInfo(type, cardData, curChooseId)
    if not cardData then
        return
    end 
    self._curChooseId = checkNumber(curChooseId)

    self._curType = checkNumber(type)
    self._cardData = cardData
    KTool.SetActive(self.ArmedForceFishing, self._curType == Constants.ChooseCardStatus.FishHangeUp)
    KTool.SetActive(self.AccompanyFishing, self._curType == Constants.ChooseCardStatus.FishAccompany)

    KTool.SetActive(self.CardInformationGroup, true)
    local isCanFish = FishingUtils.IsCardGetAndCanFishing(cardData.cardId)
    --KTool.SetActive(self.LevelUpButton2, isCanFish)
    if isCanFish then
        cardData = cardComponent:GetCardById(cardComponent:GetIdByCardId(cardData.cardId))
        self._cardData = cardData
    end

    if self._curType == Constants.ChooseCardStatus.FishAccompany then
        self:FillFishAccompanyCardInfo()
        self:FillAccompanyInfo()
    else
        self:FillCardInfo(isCanFish)
        self:FillHangUpInfo()
    end
end

