--陪钓buff
function UIFightChooseCardsFishNode:FillFishAccompanyBuffs()
    local t = FishingUtils.GetFishCardBuffData(self._cardData.cardId, self._curType)
    local count = 0
    for k, v in pairs(t) do
        count = count + 1
        local go = self.ProbabilityDescripe.transform:Find("buff"..count)
        if not go then
            go = CfUtils.InstantiateGo(self.TextNode, self.ProbabilityDescripe)
            go.name = "buff"..count
        end

        self:FillFishAccompanyBuff(go, v)
    end

    if count < (self.ProbabilityDescripe.childCount - 1) then
        for i = count + 1, (self.ProbabilityDescripe.childCount - 1) do
            local go = self.ProbabilityDescripe:GetChild(i)
            if go then
                KTool.SetActive(go, false)
            end
        end
    end
end

--绘制buff
function UIFightChooseCardsFishNode:FillFishAccompanyBuff(go, data)
    if not go then
        return
    end
    local star = checkNumber(data.starKey)
    CfUtils.FillText(go.transform:Find("TextNumber"), star)
    local status = ((checkNumber(self._cardData.star) >= star) and 2 or 1)

    CfUtils.SetUISwitchImage(go.transform:Find("TextNumber/ImgStar"), status)
    CfUtils.SetUISwitchText(go.transform:Find("TextNumber"), status)
    CfUtils.SetUISwitchText(go.transform:Find("TextDescripe"), status)
    CfUtils.FillText(go.transform:Find("TextDescripe"), FishingUtils.GetAdditionDesc(data.buffData))
    KTool.SetActive(go, true)
end


--绘制挂机信息
function UIFightChooseCardsFishNode:FillHangUpInfo()
    local path = GoodsConfMgr:GetInstance():GetPhotoPathById(Constants.Currency.HpId)
    CfUtils.FillImage(self.ImgIconGoods, path)
    self:FillFishHangUpBuffs()

    self:RefreshAllBuffList()
end

--陪钓的
function UIFightChooseCardsFishNode:FillFishAccompanyCardInfo()
    local vo = CardConfMgr:GetInstance():GetCardByRefId(self._cardData.cardId)
    if vo then
        CfUtils.FillText(self.CardName, vo.name)
    end
    local isHaveCard = cardComponent:IsHasCard(self._cardData.cardId)
    KTool.SetActive(self.TextGrade, isHaveCard)
    KTool.SetActive(self.GradeNum, isHaveCard)
    KTool.SetActive(self.StarGroup, isHaveCard)
    if isHaveCard then
        local data = cardComponent:GetCardById(cardComponent:GetIdByCardId(self._cardData.cardId))
        if data then
            --CfUtils.FillText(self.GradeNum, data.cardLevel)
            local starVo = CardConfMgr:GetInstance():GetCardStarInfo(self._cardData.cardId, self._cardData.star)
            local maxLevel = checkNumber(starVo.maxLevel)
            local isCanUpgradeLevel = checkNumber(self._cardData.cardLevel) < maxLevel
            local isCanUpgradeStar = checkNumber(self._cardData.star) < Constants.CardMaxStar
        
            if (isCanUpgradeLevel or isCanUpgradeStar) then
                CfUtils.FillText(self.GradeNum, self._cardData.cardLevel)
            else
                CfUtils.FillText(self.GradeNum, "MAX")
            end

            self.StarGroup:SetStarNo(Constants.CardMaxStar, 0, checkNumber(data.star))
        end 
    end
end 


--绘制卡牌信息
function UIFightChooseCardsFishNode:FillCardInfo(isCanFish)
    local vo = CardConfMgr:GetInstance():GetCardByRefId(self._cardData.cardId)
    CfUtils.FillText(self.CardName, vo.name)

    KTool.SetActive(self.TextGrade, isCanFish)
    KTool.SetActive(self.GradeNum, isCanFish)
    KTool.SetActive(self.StarGroup, isCanFish)
    KTool.SetActive(self.TextNumber, isCanFish)
    KTool.SetActive(self.ImgBg, isCanFish)
    KTool.SetActive(self.ImgIconGoods, isCanFish)

    local isFishing = FishingUtils.IsCardFishing(self._cardData.id)
    KTool.SetActive(self.CountdownGroup, isCanFish and not isFishing)
    KTool.SetActive(self.ImgInFishing, isFishing)

    if isCanFish then
        CfUtils.FillText(self.GradeNum, self._cardData.cardLevel)
        self.StarGroup:SetStarNo(Constants.CardMaxStar, checkNumber(self._cardData.star))
    
        local curEnergy, time = FishingUtils.GetFishCardEnergyNum(self._cardData.id)
        local maxEnergy = FishingUtils.GetFishCardMaxEnergyNum(self._cardData.cardId)
        CfUtils.FillText(self.TextNumber, curEnergy.."/"..maxEnergy)
        self.ImgBg.value = curEnergy/maxEnergy

        CfUtils.FillText(self.TextTime, CfUtils.GetTimeHMS2(time))
    end
end

--挂机buff
function UIFightChooseCardsFishNode:FillFishHangUpBuffs()
    local t = FishingUtils.GetFishCardBuffData(self._cardData.cardId, self._curType)
    local count = 0
    for k, v in pairs(t) do
        count = count + 1
        local go = self.ProbabilityDescripe2.transform:Find("buff"..count)
        if not go then
            go = CfUtils.InstantiateGo(self.TextNode2, self.ProbabilityDescripe2)
            go.name = "buff"..count
        end

        self:FillFishAccompanyBuff(go, v)
    end

    if count < (self.ProbabilityDescripe2.childCount - 1) then
        for i = count + 1, (self.ProbabilityDescripe2.childCount - 1) do
            local go = self.ProbabilityDescripe2:GetChild(i)
            if go then
                KTool.SetActive(go, false)
            end
        end
    end
end

--刷新所有的bufflist
function UIFightChooseCardsFishNode:RefreshAllBuffList()
    local t = teamComponent:GetBufferTeam()
    self._allBuffList = {}

    local buffList = {}
    if t then
        for k, v in pairs(t) do
            if checkNumber(v.cardId) > 0 then
                local buffData = FishingUtils.GetFishCardBuffData(v.cardId, self._curType)
                if buffData then
                    local data = cardComponent:GetCardById(v.refId)
                    for k, v in pairs(buffData) do
                        if checkNumber(data.star) >= checkNumber(v.starKey) then
                            table.insert(buffList, v)
                        end
                    end
                end
            end
        end
    end
    local buffMap = {}

    for k, v in pairs(buffList) do
        if buffMap[checkString(v.buffData.type)] then
            buffMap[checkString(v.buffData.type)].value = buffMap[checkString(v.buffData.type)].value + checkNumber(v.buffData.value)
        else
            buffMap[checkString(v.buffData.type)] = {
                value = checkNumber(v.buffData.value),
                buffData = v.buffData
            } 
        end
    end
    for k, v in pairs(buffMap) do
        table.insert(self._allBuffList, {
            value = v.value,
            buffData = v.buffData
        })
    end
    if self._isInitList then
        GameUtils.ReloadData(self.LoopList, table.count(self._allBuffList))
    else
        self.LoopList:InitGridView(table.count(self._allBuffList), Bind(self, self.OnRefreshIndex))
        self._isInitList = true
    end
end

function UIFightChooseCardsFishNode:OnRefreshIndex(listView, index, row, column)
    if index < 0 then
        return nil
    end

    local cell = listView:NewListViewItem("Cell")
    local data = self._allBuffList[index + 1]
    local rootGo = cell.gameObject.transform
    local textGo = rootGo.transform:Find("Text")
    local textNumberGo = rootGo.transform:Find("TextNumber")

    local addName = "+"
    local vo = FishingUtils.GetFishingBonusEffectVo(data.buffData.type)
    if vo then
        addName = (checkNumber(vo.isMinus) == 1 and "-" or "+")
    end

    CfUtils.FillText(textNumberGo, addName..checkInt(data.value * 100).."%")
    CfUtils.FillText(textGo, FishingUtils.GetAdditionNoValueDesc(data.buffData, nil, true))

    return cell
end

function UIFightChooseCardsFishNode:OnFishHangUpTimeDown()
    if not self._cardData then
        return
    end
    
    if self._curType == Constants.ChooseCardStatus.FishHangeUp then
        local curEnergy, time = FishingUtils.GetFishCardEnergyNum(self._cardData.id)
        local maxEnergy = FishingUtils.GetFishCardMaxEnergyNum(self._cardData.cardId)
        CfUtils.FillText(self.TextNumber, curEnergy.."/"..maxEnergy)
        self.ImgBg.value = curEnergy/maxEnergy
        
        CfUtils.FillText(self.TextTime, CfUtils.GetTimeHMS2(time))
    end
end

function UIFightChooseCardsFishNode:OnDestroy()
    Events.RemoveListener(Constants.EventNames.FishHangUpTimeDown, self.EventFishHangUpTimeDown)
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end

return UIFightChooseCardsFishNode





